<?php $beRoot=base_url('store/'.$settings->store_slug); ?>
<main class="be-commerce be-shell be-services-page"><nav class="be-crumbs" aria-label="Breadcrumb"><a href="<?= $beRoot; ?>">Home</a><span>/</span><span>Services</span></nav><header class="be-page-heading"><div><span class="be-eyebrow"><?= $beCopy('service_eyebrow'); ?></span><h1><?= $beCopy('service_heading'); ?></h1><p><?= $beCopy('service_intro'); ?></p></div><span class="be-page-count"><?= (int)($total ?? count($services ?? [])); ?><small><?= $beCopy('service_count_label'); ?></small></span></header>
<form class="be-collection-search" method="get" action="<?= $beRoot.'/services'; ?>"><span aria-hidden="true">⌕</span><label class="be-sr-only" for="be-services-search">Search services</label><input id="be-services-search" name="search" type="search" placeholder="<?= $beCopy('service_search'); ?>" value="<?= htmlspecialchars($search ?? ''); ?>"><button>Search ↗</button></form>
<?php if(!empty($services)): ?><div class="be-catalogue-grid be-service-collection"><?php foreach($services as $i=>$s):$policy=mp_service_price_model($s); ?><article class="be-shop-card"><a href="<?= $beRoot.'/service/'.(int)$s->id; ?>" class="be-shop-image"><?php if(!empty($s->service_image)): ?><img src="<?= htmlspecialchars(mp_storefront_image_url($s->service_image)); ?>" alt="<?= htmlspecialchars($s->service_name); ?>" loading="lazy"><?php else: ?><span class="be-service-monogram" aria-hidden="true"><?= sprintf('%02d',$i+1); ?></span><?php endif; ?></a><div class="be-shop-meta"><span><?= !empty($s->service_duration)?htmlspecialchars($s->service_duration):$beCopy('service_fallback'); ?></span></div><h2><a href="<?= $beRoot.'/service/'.(int)$s->id; ?>"><?= htmlspecialchars($s->service_name); ?></a></h2><p class="be-service-excerpt"><?= htmlspecialchars(mb_substr(strip_tags($s->description ?? ''),0,180)); ?></p><div class="be-shop-price"><?= $policy==='quote'?'Quote Required':($policy==='starting'?'From ':'').sf_currency($s->effective_price ?? $s->price,$store_currency ?? null); ?></div><a class="be-card-action" href="<?= $beRoot.'/service/'.(int)$s->id; ?>"><?= $beCopy('service_explore'); ?> <span>↗</span></a></article><?php endforeach; ?></div><?php else: ?><div class="be-empty-state"><h2><?= $beCopy('service_empty_heading'); ?></h2><p><?= $beCopy('service_empty_text'); ?></p><a class="be-pill" href="<?= $beRoot.'/services'; ?>"><?= $beCopy('service_view_all'); ?> ↗</a></div><?php endif; ?>
<?php if(($total_pages ?? 0)>1): ?><nav class="be-pagination" aria-label="Service pages"><?php if($page>1): ?><a href="<?= $beRoot.'/services?'.htmlspecialchars(http_build_query(['page'=>$page-1,'search'=>$search ?? '','category'=>$category_id ?? 0])); ?>" aria-label="Previous page">←</a><?php endif; ?><span>Page <?= (int)$page; ?> of <?= (int)$total_pages; ?></span><?php if($page<$total_pages): ?><a href="<?= $beRoot.'/services?'.htmlspecialchars(http_build_query(['page'=>$page+1,'search'=>$search ?? '','category'=>$category_id ?? 0])); ?>" aria-label="Next page">→</a><?php endif; ?></nav><?php endif; ?></main>
